function ellipseIoU(r){let area=0;for(let i=0;i<720;i++){let a=(i+.5)*Math.PI*2/720,c=Math.cos(a)**2,s=Math.sin(a)**2;area+=Math.min(1/(c/(r.L*r.L)+s/(r.H*r.H)),1/(c/(r.truthL*r.truthL)+s/(r.truthH*r.truthH)))*Math.PI/720;}return area/(Math.PI*r.L*r.H+Math.PI*r.truthL*r.truthH-area);}
